/* 科创智能体运行台：本地交互原型，不调用云端模型。 */
(() => {
'use strict';
const root=document.getElementById('pgRun');if(!root)return;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const S={agent:null,turns:[],active:null,queue:[],files:new Map(),drafts:[],refs:[],voice:'',tab:'artifacts',selected:null,mode:'Agent',permission:'default',lastLinks:[],rejectedLinks:new Set(),resolve:null};
const $=s=>root.querySelector(s),last=()=>S.turns.at(-1),active=()=>S.turns.find(t=>t.id===S.active),selected=()=>S.turns.find(t=>t.id===S.selected)||last();
const labels={parsing:'解析素材',clarify:'等待补充',plan:'等待计划确认',permission:'等待权限确认',running:'执行中',connection:'连接不可用',loop:'循环风险暂停',stopped:'用户已停止',failed:'自检未通过',complete:'已交付，等待验收',accepted:'用户已验收',cancelled:'已取消'};
const routeNames={cultivation:'加入培育项目',training:'查看培训日历',policy:'政策匹配',service:'平台服务对接',archive:'企业数字档案',knowledge:'平台技能与资料'};
const scenarios=[
['缺关键对象 → 反问','Agent','帮我改一下'],
['先确认方案，再执行交付','Plan','根据笔记生成2027年高企准备清单。','notes'],
['修改表格 → 权限确认','Agent','这份表格按销售额降序排序，保留原始数据。','csv'],
['年度冲突 → 选择或跳过','Agent','请整理申报笔记，先确认申请年度再生成清单。','conflict'],
['业务咨询 · 只提供解答','Ask','高企申报应该先准备哪些材料？'],
['连接失败 → 如实降级','Agent','查询邮箱中的申报通知并整理关键事项。',null,'failure'],
['循环风险 → 暂停确认','Agent','根据笔记生成2027年高企准备清单。','notes','loop'],
['自检未通过 → 禁止推荐','Ask','请给出我们今年申报高企的准确通过率，不能只给定性建议。']];
root.innerHTML=`<div class="ar-top"><button type="button" data-ar="back">← 智能体广场</button><div class="ar-title"><b id="ar-name">智能体运行台</b></div><button type="button" data-ar="new">新建对话</button></div>
<details class="ar-demo" hidden><summary>交互演练场景 <span>只填入输入框，点击发送才开始</span></summary><div id="ar-scenarios"></div><div class="ar-demo-options"><label><input id="ar-fail" type="checkbox">演练：连接器不可达</label><label><input id="ar-loop" type="checkbox">演练：循环调用风险</label></div></details>
<div class="ar-desk"><section class="ar-conversation"><div id="ar-history" class="ar-history"></div><div id="ar-queue" class="ar-queue" hidden></div><div class="ar-composer" id="ar-drop"><div id="ar-sources"></div><textarea id="ar-input" rows="3" placeholder="描述您的目标，可附文件或 @ 引用资料…" aria-label="本轮问题"></textarea><div class="ar-composer-bar"><button type="button" data-ar="attach">＋ 附件</button><button type="button" data-ar="reference">@ 引用</button><button type="button" data-ar="voice">语音转写</button><small>Enter 发送 · Shift+Enter 换行</small><button type="button" data-ar="stop" id="ar-stop" hidden>停止</button><button type="button" data-ar="send" class="ar-primary">发送</button></div><input type="file" multiple hidden id="ar-files"><p>最多50个附件；只在本机浏览器处理。PDF、图片及Office正文尚未接入识别。</p></div></section>
<aside class="ar-results"><div class="ar-results-heading"><div><h3>结果区</h3><p id="ar-result-context">等待用户发起</p></div><span id="ar-result-count">0</span></div><div class="ar-tabs" role="tablist"><button role="tab" data-tab="artifacts">产物</button><button role="tab" data-tab="web">网页</button><button role="tab" data-tab="workspace">工作空间文件</button><button role="tab" data-tab="changes">变更</button></div><div id="ar-result-body"></div><footer>浏览器内虚拟工作区；下载后才保存为本机文件。</footer></aside></div>
<dialog id="ar-modal"><header><div><h3 id="ar-modal-title"></h3><p id="ar-modal-note"></p></div><button type="button" data-ar="modal-close" aria-label="关闭弹窗">✕</button></header><div id="ar-modal-body"></div><footer id="ar-modal-actions"></footer></dialog>`;
const modal=$('#ar-modal');
function dialog(title,note,body,buttons){if(S.resolve){S.resolve(false);S.resolve=null;}$('#ar-modal-title').textContent=title;$('#ar-modal-note').textContent=note;$('#ar-modal-body').innerHTML=body;$('#ar-modal-actions').innerHTML=buttons.map((b,i)=>`<button type="button" data-choice="${i}" class="${b.primary?'ar-primary':''}">${esc(b.label)}</button>`).join('');if(!modal.open)modal.showModal();return new Promise(resolve=>{S.resolve=resolve;$('#ar-modal-actions').onclick=e=>{const b=e.target.closest('[data-choice]');if(!b)return;S.resolve=null;modal.close();resolve(buttons[Number(b.dataset.choice)].value);};});}
const choices=[{label:'取消',value:false},{label:'确认',value:true,primary:true}];
const info=(title,body)=>dialog(title,'本地演示状态',body,[{label:'知道了',value:true,primary:true}]);
modal.addEventListener('cancel',()=>{S.resolve?.(false);S.resolve=null;});modal.addEventListener('close',()=>{S.resolve?.(false);S.resolve=null;});
function phase(t){return !t?0:['parsing','clarify'].includes(t.status)?1:['complete','accepted'].includes(t.status)?3:2;}

const introductions={
zc:{lead:'看懂政策，找到适合企业的申报方向',description:'可以咨询政策条件、比较申报项目，或提供政策原文让我帮您梳理重点。',skills:['政策条件解读','申报方向分析','材料与时间安排'],questions:[['看懂申报条件','创新型中小企业认定需要满足哪些条件？'],['比较不同资质','高新技术企业与专精特新中小企业有什么区别？'],['分析当前企业','结合当前企业档案，分析高企申报的满足点、差距和待核验事项，给出准备规划与待办建议。'],['解读手头政策','我有一份政策通知，能帮我提炼申报条件、材料和截止时间吗？']]},
cp:{lead:'了解企业能力，找准下一步提升方向',description:'可以了解测评维度、分析企业优势与短板，或围绕目标资质讨论准备方向。',skills:['科创能力分析','资质差距梳理','能力提升建议'],questions:[['了解测评内容','企业科创能力主要从哪些维度评估？'],['分析创新能力','研发机构等级和研发团队情况如何影响企业创新能力？'],['找准培育方向','我们是科技型中小企业，下一阶段应该重点提升哪些能力？'],['对照目标找差距','我想申报创新型中小企业，需要先核查哪些企业数据？']]},
kw:{lead:'把培育目标，变成可以推进的行动',description:'可以讨论资质成长路径、拆解培育任务，并了解平台内的培训与专业服务。',skills:['培育路径规划','任务拆解','平台资源对接'],questions:[['规划下一阶段','科技型中小企业如何逐步成长为专精特新企业？'],['安排准备任务','准备明年申报高企，如何安排各阶段的工作？'],['了解培训方向','研发项目管理比较薄弱，应该优先学习哪些内容？'],['明确服务需求','申报材料整理遇到困难，平台内有哪些服务可以帮助我？']]},
sb:{lead:'先理清申报要求，再组织好申报材料',description:'可以拆解申报书结构、梳理证据清单，并根据您提供的真实素材起草或修改内容。',skills:['申报结构梳理','素材与证据整理','文稿起草修改'],questions:[['了解申报结构','一份科技项目申报书通常包含哪些核心章节？'],['梳理技术亮点','如何把产品技术特点整理成申报书中的创新点？'],['准备写作素材','起草项目申报书之前，需要提供哪些企业和项目资料？'],['修改已有文稿','我有一段项目简介，能帮我改善表达并指出缺少的依据吗？']]}
};
function welcomeHTML(){const a=S.agent||{},c=introductions[a.id]||{lead:'把您的业务问题交给我，一起找到下一步',description:a.intro||'从具体问题开始，我会先解答，再根据您的需要协助处理。',skills:['业务咨询','资料梳理','行动建议'],questions:[['了解能力','你可以帮我处理哪些问题？'],['整理资料','我想整理一份业务材料，应该先准备什么？']]};return '<div class="ar-welcome ar-agent-welcome"><span class="ar-agent-symbol">✦</span><div class="ar-welcome-eyebrow">'+esc(a.name||'科创智能体')+'</div><h2>'+esc(c.lead)+'</h2><p>'+esc(c.description)+'</p><div class="ar-capabilities">'+c.skills.map(x=>'<span>'+esc(x)+'</span>').join('')+'</div><div class="ar-question-heading"><b>您可以这样问我</b><small>点击问题填入输入框，发送后开始</small></div><div class="ar-question-examples">'+c.questions.map((q,i)=>'<button type="button" data-ar="example" data-example="'+i+'"><b>'+esc(q[0])+'</b><p>'+esc(q[1])+'</p><i>↗</i></button>').join('')+'</div></div>';}

function render(){root.classList.toggle('ar-idle',!S.turns.length);const h=$('#ar-history'),top=h.scrollTop,atEnd=h.scrollHeight-h.scrollTop-h.clientHeight<100;const t=active()||last(),p=phase(t);$('#ar-history').innerHTML=S.turns.length?S.turns.map(turnHTML).join(''):welcomeHTML();$('#ar-stop').hidden=!['parsing','running'].includes(active()?.status);$('#ar-queue').hidden=!S.queue.length;$('#ar-queue').innerHTML='<b>消息队列 · '+S.queue.length+' 条</b>'+S.queue.map((p,i)=>`<div><span>${i+1}. ${esc(p.text||'附件输入')}</span><button type="button" data-ar="dequeue" data-index="${i}">取消</button></div>`).join('');renderSources();renderResults();h.scrollTop=atEnd?h.scrollHeight:top;}
function turnHTML(t,index){const c=t.card,open=t===active()||t===last(),time=t.ended?((t.ended-t.started)/1000).toFixed(1)+'秒':'本轮处理中';return `<article class="ar-turn" data-turn="${t.id}"><div class="ar-user"><div><small>您 · 第${index+1}轮</small><p>${esc(t.packet.text||'请处理所提供素材')}</p><div class="ar-user-sources">${[...t.packet.files.map(f=>f.name),...t.packet.refs.map(r=>'@'+r.title),...(t.packet.voice?['语音转写 · 用户确认']:[])].map(x=>'<span>'+esc(x)+'</span>').join('')}</div></div></div>${t.events.map(e=>'<div class="ar-followup"><b>您补充</b>'+esc(e)+'</div>').join('')}
${t.status==='clarify'?questionHTML(t):''}${t.status==='plan'?planHTML(t):''}
${!t.enterprise&&['parsing','running'].includes(t.status)?'<div class="ar-replying" role="status"><i></i>正在回复…</div>':''}
${['permission','connection','loop','stopped'].includes(t.status)?pauseHTML(t):''}
${t.enterprise?enterpriseHTML(t):''}${t.answer&&!t.enterprise?`<section class="ar-answer" aria-label="智能体回复"><div>${esc(t.answer)}</div>${t.mode==='Ask'&&['生成','修改'].includes(c.action)?`<button type="button" class="ar-link" data-ar="switch-agent" data-turn="${t.id}">生成文件并重新提交 →</button>`:''}${t.outputs.length?'<p class="ar-result-pointer">产物已放入右侧结果区，修改任务请先查看“变更”。</p>':''}</section>`:''}
${t.status==='failed'?recoveryHTML(t):''}${['complete','accepted'].includes(t.status)?guideHTML(t):''}${t.status==='cancelled'?'<p class="ar-blocked">操作已取消，未执行写入或对外发送。</p>':''}${t===last()&&['complete','accepted','failed'].includes(t.status)?`<div class="ar-reply-tools"><button type="button" data-ar="refresh" data-turn="${t.id}">重新生成最后回复</button><button type="button" data-ar="show-turn" data-turn="${t.id}">查看本轮结果</button></div>`:''}${t.ended&&c?flowHTML(t):''}</article>`;}
function flowHTML(t){const c=t.card,route=c.links[0],answered=!!t.answer,good=t.checks.length&&t.checks.every(x=>x.pass),audit=(title,items)=>'<section><b>'+title+'</b><dl>'+items.map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl></section>';return '<details class="ar-flow-record"><summary>查看本轮处理记录 <small>输入 → 理解 → 解答 → 后续操作</small></summary>'+audit('理解输入',[
['输入解析',t.packet.files.length+' 个附件，'+t.packet.refs.length+' 个指定引用；'+(t.packet.voice?'已确认语音文本':'用户文字输入')],
['意图识别',c.action+'：'+c.goal],
['承接判定',route?.kind==='系统功能'?'优先对应平台功能：'+route.title+'；先解答，再由您选择进入':route?.kind==='系统知识库'?'使用平台知识与方法解答；按需引导资料入口':'系统内暂无已核验承接能力；外部来源未接入，不虚构结果'],
['上下文',c.materials.map(m=>m.source).join('；')],
['缺口与冲突',t.status==='clarify'?t.question:c.conflicts.length?c.conflicts.join('；'):c.pending.length?c.pending.join('；'):'未发现阻塞本轮的关键缺口'],
['理解卡',c.action+'；'+c.scope+'；验收：'+c.acceptance]
])+audit('回答与交付',[
['处理计划',t.status==='plan'?'等待您确认计划，尚未执行':c.plan.join(' → ')],
['执行方式','本地交互原型：可读取文本、排序CSV、生成文件；未接入真实模型或外部连接器'],
['中途校验',t.status==='permission'?'等待您确认修改范围':t.status==='connection'?'连接失败，等待重试或调整范围':t.status==='loop'?'检测到循环风险，已暂停':t.status==='stopped'?'已按您的操作停止':t.status==='running'?'执行中，可停止；新消息进入队列':'按本轮授权范围处理'],
['产出与自检',!answered?'尚未产出':good?'已按本轮检查项完成核对':t.checks.filter(x=>!x.pass).map(x=>x.note).join('；')||'尚未完成检查'],
['交付位置',t.outputs.length?'右侧结果区：'+t.outputs.map(x=>x.split('/').pop()).join('、'):answered?'本轮对话内解答，没有生成文件':'尚未交付']
])+audit('引导与收口',[
['联动推荐',!good?'本轮未完成，不展示推荐':t.dismissed?'您已跳过，不再重复推荐':t.recommendations.length?t.recommendations.map(x=>x.title).join('；'):'本轮无需额外入口或已避免重复推荐'],
['资料沉淀', '仅在您点击并确认后保存到当前浏览器；未接入云端'],
['下一轮',t.status==='accepted'?'已验收，等待您发起新问题':'由您补充、修改、验收或选择下一步；不会自动发起新轮次']
])+'</details>';}
function nextHTML(t){const prompts=t.card.action==='查询'||t.card.action==='分析'?['请把刚才的建议整理成准备清单，标明需要我确认的事项。','请详细解释刚才提到的材料要求，不生成文件。']:['请检查这份结果还有哪些待确认事项，先在对话里说明。','请先给出修改这份结果的计划，确认后再执行。'];return '<div class="ar-next-prompts"><b>您还可以继续问</b>'+prompts.map(q=>'<button type="button" data-ar="prompt" data-turn="'+t.id+'" data-prompt="'+esc(q)+'">'+esc(q)+'</button>').join('')+'</div>';}
function recoveryHTML(t){const q=/最新|变化|实时/.test(t.packet.text)?'请先列出高企申报政策需要核查的条款和材料，说明核查方法。':/通过率|概率/.test(t.packet.text)?'请先列出高企申报前需要核查的条件和证据，不给出量化结论。':'请先说明本轮尚缺哪些资料，以及有依据可以回答的部分。';return '<section class="ar-recovery"><b>还需要补充依据</b><p>'+esc(t.checks.filter(x=>!x.pass).map(x=>x.note).join('；')||'本轮目标尚未完成。')+'</p><p>补充附件或 @ 引用后发送，继续处理；也可以先明确核查范围。</p><button type="button" data-ar="prompt" data-turn="'+t.id+'" data-prompt="'+esc(q)+'">先帮我明确核查范围 →</button></section>';}
function cardHTML(c){return `<dl class="ar-card-grid">${[['目标',c.goal],['处理方式',c.action],['目标文件',c.target||'未指定既有文件'],['授权范围','/workspace/科创任务/（虚拟）'],['交付格式',c.mode==='Ask'?'只在对话区解答':c.format],['验收标准',c.acceptance]].map(([k,v])=>'<div><dt>'+k+'</dt><dd>'+esc(v)+'</dd></div>').join('')}</dl><div class="ar-card-sources"><b>素材与来源</b>${c.materials.length?c.materials.map(m=>'<p><span>'+esc(m.source)+'</span>'+esc(m.summary)+(m.required?'<em>用户指定必须纳入</em>':'')+(m.annotation?' · 批注：'+esc(m.annotation):'')+'</p>').join(''):'<p>仅本轮问题；未调用企业档案。</p>'}</div><div class="ar-card-lists">${[['假设',c.assumptions],['待定',c.pending],['冲突',c.conflicts]].map(([k,v])=>'<div><b>'+k+'</b><p>'+(v.length?v.map(esc).join('<br>'):'无')+'</p></div>').join('')}</div><details class="ar-card-more"><summary>执行计划与联动位</summary><ol>${c.plan.map(p=>'<li>'+esc(p)+'</li>').join('')}</ol><p><b>承接判定：</b>${c.links.map(l=>esc(l.kind+' · '+l.title)).join('；')}</p><p>此处仅记录联动位，专业解答自检通过前不放行推荐。</p></details>`;}
function questionHTML(t){return `<section class="ar-question"><b>${t.conflict?'发现信息冲突':'需要确认关键对象'}</b><p>${esc(t.question)}</p><div>${t.options.map((o,i)=>`<button type="button" data-ar="clarify" data-turn="${t.id}" data-index="${i}"><b>${esc(o.label)}</b><small>${esc(o.cost)}</small></button>`).join('')}</div><button type="button" class="ar-link" data-ar="skip" data-turn="${t.id}">跳过，由助手采用安全假设并明确标注</button><small>也可在输入框补充说明，缺口确认后重新解析。</small></section>`;}
function planHTML(t){return `<section class="ar-plan"><h4>执行方案 · v${t.planVersion}</h4><p><b>目标：</b>${esc(t.card.goal)}</p><ol>${t.card.plan.map(x=>'<li>'+esc(x)+'</li>').join('')}</ol><p><b>产物清单：</b>${t.card.action==='查询'?'仅对话结论':esc(t.card.format)+'及对应变更记录'}</p><p><b>风险：</b>来源不完整、原始口径冲突及未定信息须保留。</p><p><b>明确不做：</b>不覆盖原始附件、不上传云端、不自动付费或发送。</p><div class="ar-action-row"><button type="button" data-ar="execute" data-turn="${t.id}" class="ar-primary">开始执行</button><button type="button" data-ar="adjust" data-turn="${t.id}">调整计划</button></div><small>尚未生成文件；必须点击开始执行。</small></section>`;}
function pauseHTML(t){const options={permission:['等待操作确认','修改已有文件前，需要由您确认。','permission','查看权限请求'],connection:['连接器不可达（演练）','没有取得邮箱数据，已停止相关调用。','retry','检查并重试'],loop:['循环风险已暂停（演练）','工具调用前检测到可能重复执行。','continue-loop','仅继续执行一次'],stopped:['本轮已停止','已完成的中间内容仍然保留，可调整后重发或继续。','resume','基于已有内容继续']};const [title,note,action,label]=options[t.status];return `<section class="ar-paused"><b>${title}</b><p>${note}</p><div class="ar-action-row"><button type="button" data-ar="${action}" data-turn="${t.id}">${label}</button>${t.status==='connection'?`<button type="button" data-ar="degrade" data-turn="${t.id}">降级：只用当前素材</button>`:''}<button type="button" data-ar="terminate" data-turn="${t.id}">终止请求</button></div></section>`;}
function guideHTML(t){return `<section class="ar-guide" aria-label="相关操作">${t.card.pending.length||t.card.assumptions.length?'<details><summary>待办与确认清单</summary><ul>'+[...t.card.pending.map(x=>'待定：'+x+'；建议向资料负责人核对'),...t.card.assumptions.map(x=>'假设：'+x+'；可在下一轮更正')].map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></details>':''}${!t.dismissed&&!t.enterprise?t.recommendations.map(l=>`<button type="button" class="ar-guidance-card" data-ar="navigate" data-link="${l.id}" data-turn="${t.id}"><b>${esc(l.title)} →</b><small>${esc(l.kind+' · '+l.note)}</small></button>`).join(''):''}${nextHTML(t)}<div class="ar-action-row"><button type="button" class="ar-primary" data-ar="add-project" data-turn="${t.id}">${t.addedProject?'已添加到培育项目':'添加到培育项目'}</button></div></section>`;}
function renderSources(){$('#ar-sources').innerHTML=S.drafts.map((f,i)=>`<span>📎 ${esc(f.name)}<button type="button" data-ar="remove-file" data-index="${i}">×</button></span>`).join('')+S.refs.map((r,i)=>`<span>@ ${esc(r.title)}<button type="button" data-ar="remove-ref" data-index="${i}">×</button></span>`).join('')+(S.voice?'<span>转写文本 · 已确认<button type="button" data-ar="remove-voice">×</button></span>':'');}
function readMemory(){try{return JSON.parse(localStorage.getItem('whkc-agent-confirmed-memory')||'[]');}catch{return [];}}
function classify(text,history){
const question=/哪些|什么|如何|怎么|是否|能否|有什么|需要.*吗|可以.*吗|[？?]/.test(text),explicit=/^(请|帮我|麻烦|现在|根据[^，。\n]*[，,]?)?(生成|起草|撰写|输出|制作|整理成|把.+整理|修改|润色|重写|排序)/.test(text.trim())||/生成.{0,15}(文档|文件|清单|报告|Word|表格)|另存|导出|\bCSV\b/i.test(text);
const modify=(!question||explicit)&&/修改|改一下|调整|润色|排序|重写|改成|删除/.test(text),create=(!question||explicit)&&/生成|写一|做一|整理|输出|出一|制作|起草|撰写/.test(text);let action=modify?'修改':create?'生成':/分析|统计|对比|评估|通过率/.test(text)?'分析':'查询';if(text.trim().length<4)action='澄清';let topic=/高企|高新技术/.test(text)?'hightech':/培训|课程|系统学/.test(text)?'training':/专利|知识产权|软著/.test(text)?'ip':/财税|审计|研发费用|辅助账|税/.test(text)?'tax':/申报书|大纲|章节/.test(text)?'writing':/培育|专精特新|小巨人|创新型中小企业/.test(text)?'plan':/政策|补贴|匹配/.test(text)?'policy':null;if(!topic&&history&&/材料|继续|多少钱|下一步|怎么|这个|这份|刚才|本轮|上轮|改|排序/.test(text))topic=history.card?.topic;return {action,topic,ambiguous:modify&&create};}

function linksFor(text,topic){const links=[],names={cultivation:'加入培育项目',training:'查看培训日历',policy:'政策匹配',service:'平台服务对接',archive:'企业数字档案'};const add=(id,note)=>{if(!links.some(x=>x.id===id))links.push({id,title:names[id],kind:'系统功能',note});};if(/长期|通过率|有人带|培育|辅导/.test(text)||['hightech','plan','writing'].includes(topic))add('cultivation','在培育项目中拆解准备任务');if(/培训|课程|系统学/.test(text)||topic==='training')add('training','查看平台已发布的培训安排');if(/政策|匹配|能报|申报项目/.test(text)||topic==='policy')add('policy','按具体政策查看条件与档案支撑');if(/机构|代办|服务|费用|多少钱|收费/.test(text))add('service','先核对平台服务范围及交付约定');if(['ip','tax'].includes(topic))add('archive','查看与本轮相关的档案依据');if(!links.length&&topic)links.push({id:'knowledge',title:'平台技能与资料',kind:'系统知识库',note:'查看已有方法与工具'});if(!links.length)links.push({id:'outside',title:'系统外内容待用户指定',kind:'外部兜底',note:'系统内暂无对应能力；没有核验来源，不生成外部机构链接'});return links;}
async function parsePacket(t){const parts=[];t.unread=[];t.sourceFiles=[];if(!t.packet.files.length&&!t.packet.refs.length&&/修改|调整|排序|继续.*改/.test(t.packet.text)&&S.files.size===1){const f=Array.from(S.files.values())[0];t.sourceFiles.push({name:f.name,text:f.text,blob:f.blob,read:true,source:'工作区已有文件'});parts.push(f.text);}for(const file of t.packet.files){if(t.abort.signal.aborted)throw new DOMException('Stopped','AbortError');const read=/\.(txt|md|csv|json|log)$/i.test(file.name)&&file.size<=5*1024*1024,text=read?await file.text():'';t.sourceFiles.push({name:file.name,text,blob:file,read});if(read)parts.push(text);else t.unread.push(file.name);}for(const r of t.packet.refs){parts.push(r.text);if(r.path)t.sourceFiles.push({name:r.title,text:r.text,blob:new Blob([r.text]),read:true,source:r.source});}if(t.packet.voice)parts.push(t.packet.voice);t.sourceText=parts.join('\n\n');}
function understand(t){const previous=S.turns.slice(0,S.turns.indexOf(t)).reverse().find(x=>x.card),combined=t.packet.text+'\n'+(t.enterprise?t.enterprise.userSourceText:t.sourceText),intent=classify(t.packet.text,previous),action=t.overrideAction||intent.action;const materials=[...t.sourceFiles.map(f=>({source:(f.source||'附件')+' · '+f.name,summary:f.read?f.text.slice(0,150):'仅有文件元信息，正文未解析',required:true})),...t.packet.refs.map(r=>({source:r.source,summary:r.text.slice(0,150),required:true,annotation:r.annotation}))];if(t.packet.voice)materials.push({source:'语音转写 · 用户确认文本',summary:t.packet.voice,required:true});if(previous&&/继续|这个|上轮|刚才|下一步/.test(t.packet.text))materials.push({source:'历史对话 · 第'+(S.turns.indexOf(previous)+1)+'轮',summary:previous.card.goal});materials.unshift({source:'本轮用户消息',summary:t.packet.text.slice(0,180),required:true});const targets=[...t.sourceFiles.map(f=>f.name),...t.packet.refs.filter(r=>r.path).map(r=>r.path)];const assumptions=[...t.assumptions];if(!/验收[：:]|验收标准[：:]/.test(t.packet.text))assumptions.push('验收标准按当前任务类型设置，见理解卡；可在下一轮更正。');if(!/格式|Word|docx|CSV|HTML|网页|表格/i.test(t.packet.text)&&['生成','修改'].includes(action))assumptions.push('未指定格式，默认交付Word；表格任务交付CSV。');if(intent.ambiguous)assumptions.push('生成与修改同时出现，已按修改理解，先定位原件。');if(/排序/.test(combined)&&!/升序|降序/.test(combined))assumptions.push('未指定排序方向，默认数值降序，原始行数据保持不变。');const years=[...new Set([...combined.matchAll(/(?:申报|认定|目标|申请)(?:年度|年份)?[：:\s]*(20\d{2})|(20\d{2})年(?:申报|认定|高企)/g)].map(m=>m[1]||m[2]))];for(const file of t.sourceFiles){const m=/(20\d{2})年.*申报/.exec(file.name);if(m&&!years.includes(m[1]))years.push(m[1]);}const conflicts=years.length>1&&!t.year?['年度冲突：'+years.join(' 年 与 ')+' 年']:[];const pending=[...t.pending,...t.sourceText.split(/\r?\n/).filter(line=>/待定|未定|待确认|不确定/.test(line)).map(line=>'素材待定：'+line),...t.unread.map(name=>'附件 '+name+' 正文待识别'),...(t.degraded?['未取得外部服务数据，相关结论待核验']:[])];t.card={goal:t.packet.text,action,topic:intent.topic,topicName:{hightech:'高新技术企业认定',policy:'政策机会',ip:'知识产权',tax:'研发与财税',plan:'企业培育',writing:'申报材料',training:'培训学习'}[intent.topic]||'当前业务任务',mode:t.mode,target:t.target||targets[0]||'',scope:'仅本轮附件、用户选定引用及虚拟任务区',format:/表格|排序|CSV/i.test(combined)?'CSV 表格':/网页|页面|HTML/i.test(combined)?'HTML 网页':'Word 文档',materials,assumptions,pending:[...new Set(pending)],conflicts,plan:['读取用户明确提供的素材与引用','梳理业务事实、目标与约束',(['生成','修改'].includes(action)?'生成本轮文件并保留原始素材':'直接回答业务问题，不创建文件'),'核验来源、原始数据、假设与验收标准'],links:linksFor(t.packet.text,intent.topic),acceptance:/通过率|概率/.test(t.packet.text)?'给出有可靠依据的量化评估；无依据不得编造':t.mode==='Ask'?'只在对话中给出可追溯解答，不生成或修改文件':/排序/.test(combined)?'按指定列排序，原始行数与每行数据不变':['查询','分析'].includes(action)?'正面回答问题，明确适用范围与待核验信息':'产物可打开，覆盖用户素材，并显式列出待定与假设'};const acceptance=/(?:验收标准|验收)[：:]([^\n]+)/.exec(t.packet.text);if(acceptance)t.card.acceptance=acceptance[1].trim();if(t.enterprise){t.card.materials.push({source:t.enterprise.source,summary:t.enterprise.company+'；'+t.enterprise.known.length+'项相关档案数据',required:true});t.card.scope+='及本轮请求分析的当前企业档案';t.card.plan=['读取当前企业档案与来源','梳理企业数据与资质现状','逐项对照目标条件，区分支撑、差距和待核验','形成总体规划、待办建议并核验交付边界'];}const needsProfile=!t.enterprise&&!t.generalOnly&&!t.packet.refs.length&&!t.packet.files.length&&/我们|我司|本企业/.test(t.packet.text)&&/能否|是否|能报|适合|符合|能不能/.test(t.packet.text);const missing=action==='修改'&&!t.card.target,vague=!t.resolved&&(action==='澄清'||(!intent.topic&&/帮我.*(推荐|申报|弄)|^推荐项目$/.test(t.packet.text)));t.route=t.card.links[0];if(!t.skipped&&(conflicts.length||missing||vague||needsProfile)){t.status='clarify';t.conflict=!!conflicts.length;if(conflicts.length){t.question=conflicts[0]+'。本轮按哪一年处理？';t.options=years.slice(0,3).map(year=>({label:'采用 '+year+' 年',cost:'选择本轮口径，不改原始资料',year}));}else if(needsProfile){t.question='要判断贵企业是否满足申报条件，需要先明确目标项目、年度和企业依据。您希望如何继续？';t.options=[{label:'@引用企业档案',cost:'只读取您勾选的指标，不自动调用整份档案',reference:true},{label:'上传企业材料与政策原文',cost:'根据您实际提供的内容核对',attach:true},{label:'先解释一般申报条件',cost:'仅作业务解答，暂不判断贵企业是否符合',general:true}];}else if(missing){t.question='请确定要修改的文件，可上传原件或@引用已有产物。';t.options=[{label:'上传原件',cost:'保留原始附件，仅修改虚拟副本',attach:true},{label:'@引用已有文件',cost:'核对目标文件后记录版本变更',reference:true},{label:'改为另存新成品',cost:'不动原件，重新生成一份',action:'生成'}];}else{t.question='这次希望先处理哪类问题？';t.options=[{label:'了解高企准备',cost:'先给业务解答，不生成文件',topic:'高企申报准备',action:'查询'},{label:'查询政策机会',cost:'先明确政策与适用对象',topic:'政策匹配',action:'查询'},{label:'整理为新清单',cost:'使用明确标注的默认格式',action:'生成'}];}return false;}if(t.skipped&&missing){t.card.action='生成';t.card.target='';t.card.assumptions.push('已跳过文件选择：不修改任何原件，另存一份通用草稿。');}return true;}
function getPacket(){return {text:$('#ar-input').value.trim(),files:[...S.drafts],refs:S.refs.map(r=>({...r})),voice:S.voice,mode:/先.{0,12}(计划|方案)|确认.{0,8}(计划|方案).{0,8}(再|后).{0,5}执行/.test($('#ar-input').value)?'Plan':S.mode,permission:S.permission,failure:$('#ar-fail').checked,loop:$('#ar-loop').checked};}
async function prepare(t){try{await parsePacket(t);if(!setupEnterprise(t)){render();return;}if(t.abort.signal.aborted){t.status='stopped';render();return;}const ready=understand(t);render();if(ready)continueTurn(t);}catch(e){t.status=e.name==='AbortError'?'stopped':'failed';t.answer='素材读取未完成：'+e.message;render();}}
async function submit(custom){const p=custom||getPacket();if(p.files.length+(active()?.status==='clarify'?active().packet.files.length:0)>50){info('附件数量超过限制','<p>包括本轮补充的附件在内，最多50个文件。</p>');return;}if(!p.text&&!p.files.length&&!p.refs.length&&!p.voice)return;if(!custom){$('#ar-input').value='';S.drafts=[];S.refs=[];S.voice='';}const current=active();if(current&&['parsing','running','permission','connection','loop'].includes(current.status)){S.queue.push(p);render();return;}if(current?.status==='clarify'){current.events.push(p.text||'补充了素材');current.packet.files.push(...p.files);current.packet.refs.push(...p.refs);current.packet.voice+=p.voice;if(/20\d{2}/.test(p.text)){current.year=/20\d{2}/.exec(p.text)[0];current.assumptions.push('用户确认本轮采用 '+current.year+' 年，原始数据不变。');}if(p.text){current.packet.text+='\n补充要求：'+p.text;current.resolved=true;}current.status='parsing';current.abort=new AbortController();render();prepare(current);return;}if(current?.status==='plan'){current.packet.text+='\n计划补充：'+p.text;current.events.push(p.text);current.planVersion++;await parsePacket(current);understand(current);current.status='plan';render();return;}if(/^(不用了|不需要|跳过推荐|不要推荐|别推荐)[。！!\s]*$/.test(p.text)&&last()?.recommendations.length){last().events.push(p.text);last().dismissed=true;last().enterprise?.actions.filter(a=>a.service).forEach(a=>S.rejectedLinks.add('service:'+a.service.id));last().recommendations.forEach(l=>S.rejectedLinks.add(l.id));render();return;}const t={id:uid(),packet:p,mode:p.mode,permission:p.permission,started:Date.now(),ended:null,status:'parsing',events:[],assumptions:[],pending:[],steps:[],outputs:[],checks:[],answer:'',delivery:'',recommendations:[],dismissed:false,abort:new AbortController(),snapshot:new Map(S.files),planVersion:1};S.turns.push(t);S.active=t.id;S.selected=t.id;render();prepare(t);}
async function continueTurn(t){if((t.mode==='Plan'||/先.{0,6}(计划|方案)|确认.{0,6}(计划|方案).{0,6}(再|后)|先别执行/.test(t.packet.text))&&!t.planConfirmed){t.status='plan';render();return;}const sensitive=t.card.action==='修改'||/删除|对外发送|发送给|发到.*微信|工作区外|[A-Z]:\\/i.test(t.packet.text);if(sensitive&&t.mode!=='Ask'&&t.permission==='default'&&!t.permissionConfirmed){t.status='permission';render();permission(t);return;}execute(t);}
async function permission(t){const approved=await dialog('确认本轮操作范围','由您确认后再修改文件',`<p>目标：${esc(t.card.goal)}</p><ul><li>目标文件：${esc(t.card.target||'本轮虚拟产物')}</li><li>写入位置：/workspace/科创任务/（虚拟目录）</li><li>保留原始附件，仅修改虚拟副本。</li><li>不访问其他磁盘目录、不实际删除或对外发送。</li></ul>`,[{label:'取消本轮',value:false},{label:'确认，按此范围执行',value:true,primary:true}]);if(S.active!==t.id)return;if(!approved){t.status='cancelled';t.ended=Date.now();render();drain();return;}t.permissionConfirmed=true;execute(t);}
const delay=(ms,signal)=>new Promise((resolve,reject)=>{if(signal.aborted){reject(new DOMException('Stopped','AbortError'));return;}const timer=setTimeout(done,ms);function done(){signal.removeEventListener('abort',abort);resolve();}function abort(){clearTimeout(timer);reject(new DOMException('Stopped','AbortError'));}signal.addEventListener('abort',abort,{once:true});});
function safeCsv(v){v=String(v??'');return '"'+(/^[=+@]|^-\D/.test(v)?"'"+v:v).replace(/"/g,'""')+'"';}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=c;}row.push(cell);if(row.some(Boolean))rows.push(row);return rows;}

function setupEnterprise(t){
 const text=t.packet.text,previous=S.turns.slice(0,S.turns.indexOf(t)).reverse().find(x=>x.enterprise);
 const requested=/(当前企业|我们|我司|本企业|企业档案|企业数据|企业画像|现有档案)/.test(text)&&/分析|评估|差距|对比|规划|建议|申报|能报|诊断|条件/.test(text);
 const followup=previous&&/上述|刚才|这份|继续|这些|待办|规划/.test(text);
 if(t.generalOnly||(!requested&&!followup))return true;
 const target=t.assessmentTarget||(/高企|高新技术/.test(text)?'高新技术企业认定':/专精特新|小巨人/.test(text)?'专精特新中小企业认定':/创新型中小/.test(text)?'创新型中小企业认定':/科技型中小/.test(text)?'科技型中小企业评价':followup?previous.enterprise.target:null);
 if(!target){t.status='clarify';t.question='我会先读取当前企业档案，再对照目标找出满足点、差距和待核验事项。您希望以哪个目标开展分析？';t.conflict=false;t.options=[{label:'高新技术企业认定',cost:'对照研发、知识产权、人员及收入等条件',assessmentTarget:'高新技术企业认定'},{label:'创新型中小企业认定',cost:'对照创新、成长和专业化基础',assessmentTarget:'创新型中小企业认定'},{label:'专精特新中小企业认定',cost:'对照前序资质、专业化和创新基础',assessmentTarget:'专精特新中小企业认定'}];return false;}
 const facts=(window.getArchiveGraphFacts?.()||[]).map(f=>({...f,links:[...(f.links||[])]}));
 const requirements=target==='创新型中小企业认定'?[policyGraphRequirement('企业正常经营','企业基础','经营状态','operating'),policyGraphRequirement('具备有效知识产权及权属依据','知识产权','有效发明专利数量','positive'),policyGraphRequirement('创新能力、成长性及专业化按本批标准核验','财务成长','营收复合增长率'),policyGraphRequirement('研发投入与创新活动有据可查','科研投入','研发费用占营收比'),policyGraphRequirement('主营业务及产品专业化具备依据','财务成长','主营业务收入占比'),policyGraphRequirement('不属于失信等限制主体','信用合规','是否为失信被执行人','exclusion')]:policyGraphRequirements(target);
 const items=requirements.map(req=>evaluatePolicyGraphRequirement(req,facts));
 const known=facts.filter(f=>['知识产权','科创资质','科创平台','科技项目','科研投入','人才团队','财务成长','企业基础','信用合规'].includes(f.dimension));
 const actions=items.filter(x=>x.state!=='support').map((x,i)=>({title:(x.state==='gap'||x.state==='boundary'?'补强 / 核查：':'核验：')+x.req.label,owner:/财务|科研投入/.test(x.req.dimension)?'财务与研发负责人':/知识产权/.test(x.req.dimension)?'知识产权负责人':'申报负责人',period:i<2?'建议第1周':'建议第2周',output:x.req.field+'的有效数据、适用口径与原始凭证',state:x.state}));
 t.enterprise={userSourceText:t.sourceText,company:(document.getElementById('current-enterprise')?.textContent||'当前企业').trim(),target,facts,known,items,actions,phase:0,readAt:new Date().toLocaleString('zh-CN'),source:'企业数字档案 · 当前原型示例快照'};
 t.enterprise.actions=enterpriseTasks(t.enterprise);t.sourceText+='\n企业档案快照（模拟数据）\n'+known.map(f=>f.dimension+' / '+f.name+'：'+f.value).join('\n');
 return true;
}

function enterpriseTasks(e){
 const fact=name=>e.facts.find(f=>f.name===name)?.value||'待核验';
 const common=[{id:'scope',title:'确认申报年度、批次与资质有效期',owner:'申报负责人',period:'建议第1–2个工作日',dependency:'无前置任务',steps:['确认目标项目及主管部门当期申报通知。','核对已有资质证书、有效期和申报历史，明确首次申报或复核准备。'],deliverables:['目标项目与批次确认表','资质证书及有效期台账'],acceptance:'目标年度、批次、申报类型、通知来源均已记录；不确定事项单独标记。',state:'pending'},
 {id:'ip-evidence',title:'核验知识产权权属与主营产品关联',owner:'知识产权负责人、技术负责人',period:'建议第2–4个工作日',dependency:'先确认目标项目',steps:['核对有效发明专利 '+fact('有效发明专利数量')+'、实用新型 '+fact('实用新型专利数量')+'与软著 '+fact('软件著作权登记数量')+'的证书及有效状态。','按主营产品整理对应知识产权、权属凭证和使用说明。'],deliverables:['知识产权有效状态清单','产品—知识产权关联表'],acceptance:'每项关联均可定位到证书和产品；权属、有效期无法确认时标为待核验。',state:e.items.find(x=>x.req.field==='有效发明专利数量')?.state||'pending'}];
 const generated=e.items.filter(x=>x.state!=='support'&&x.req.field!=='有效发明专利数量').map((x,i)=>{
 const rd=/研发费用|研发投入/.test(x.req.field),people=/人员/.test(x.req.field),income=/收入/.test(x.req.field),growth=/增长/.test(x.req.field);
 const config=rd?{title:'复核近三年研发费用归集与占比',owner:'财务负责人、研发负责人',steps:['以档案研发费用占比 '+fact('研发费用占营收比')+' 为起点，核对对应统计年度及分母口径。','逐年核对项目立项、研发辅助账和原始凭证，列明需调整的费用及原因。'],deliverables:['分年度研发费用归集核对表','研发费用辅助账与凭证索引'],acceptance:'归集表、辅助账与财务报表可勾稽；各项调整均有说明和凭证。'}:
 people?{title:'核验科技人员名单与统计口径',owner:'人事负责人、研发负责人',steps:['核对档案研发人员占比 '+fact('研发人员占比')+' 的年度、人员范围和统计时点。','整理在岗名单、岗位职责及劳动关系等依据，区分研发人员与政策要求的人员口径。'],deliverables:['人员统计与占比复核表','人员岗位与证明材料索引'],acceptance:'人数、占比与统计期间一致；人员类别差异和缺失证明均有记录。'}:
 income?{title:'梳理产品收入分类及凭证对应关系',owner:'财务负责人、销售负责人、技术负责人',steps:['复核 '+x.req.field+' 当前值 '+(x.fact?.value||'待核验')+'，明确收入年度、分母和产品范围。','逐笔或按可追溯汇总口径，建立产品、销售收入、合同发票与技术依据的对应关系。'],deliverables:['产品收入分类明细表','收入—合同发票—技术依据索引'],acceptance:'分类口径与年度报表可勾稽；每类收入有业务及技术依据，差异单独解释。'}:
 growth?{title:'核对近三年经营增长数据',owner:'财务负责人',steps:['按同一口径取得近三年年度报表和收入数据。','复核增长计算方法，记录异常波动及原因。'],deliverables:['三年经营数据核验表','增长计算与差异说明'],acceptance:'原始年度数据、公式与结论可复核，不混用统计口径。'}:
 {title:(['gap','boundary'].includes(x.state)?'处理：':'核验：')+x.req.label,owner:'申报负责人',steps:['取得 '+x.req.field+' 的有效记录及原始凭证。','对照当期要求核验，记录结论、限制或待补材料。'],deliverables:[x.req.field+'核验记录','相关凭证与问题说明'],acceptance:'每项判断有来源和核验日期；未解决的问题有负责人及后续动作。'};
 return {id:'condition-'+i,...config,period:i<2?'建议第3–5个工作日':'建议第2周',dependency:'完成申报口径确认；可与其他核验任务并行',state:x.state,field:x.req.field};
 });
 const final={id:'final-review',title:'汇总材料缺口并开展申报前复核',owner:'申报负责人、各材料负责人',period:'前述核验任务完成后，建议第2周',dependency:'所有核验任务形成明确结论',steps:['汇总条件、企业数据、凭证与缺口的一一对应表。','逐项确认补强动作和责任人；存在限制或关键缺口时先处理，再决定申报安排。'],deliverables:['条件与证据核验总表','材料缺口及整改清单','内部复核意见'],acceptance:'各项条件均有支撑、差距或待核验结论；关键问题未解决时不得记为已满足。',state:'pending'};
 const tasks=[...common,...generated,final];let budget=2;const assigned=new Set();
 const priority=[...tasks].sort((a,b)=>(a.state==='gap'?-1:0)-(b.state==='gap'?-1:0));
 for(const task of priority){let productId=null,reason='';
 if(task.field&&/研发费用/.test(task.field)){productId='KC-RPT-006';reason='对应本任务的研发费用口径与归集复核，可协助形成合规审查意见。';}
 else if(task.field&&/收入/.test(task.field)&&/高新技术/.test(e.target)){productId='KC-FIN-002';reason='对应本任务的收入及研发数据专项核验；具体审计范围和出具要求需在详情中确认。';}
 else if(task.id==='ip-evidence'&&task.state==='gap'){productId='KC-IP-002';reason='对应知识产权基础缺口，先盘点资产与布局方向，再决定后续申请安排。';}
 const product=productId&&typeof MALL_PRODUCTS!=='undefined'?MALL_PRODUCTS.find(p=>p.id===productId):null;
 if(product&&budget&&!assigned.has(product.id)&&!S.lastLinks.includes('service:'+product.id)&&!S.rejectedLinks.has('service:'+product.id)){task.service={id:product.id,name:product.name,reason,price:(product.priceMain+' '+product.priceUnit).trim()};assigned.add(product.id);budget--;}
 task.output=task.deliverables.join('、');
 }
 return tasks;
}
function enterpriseTasksHTML(t){const e=t.enterprise,canRecommend=['complete','accepted'].includes(t.status);return '<div class="ar-specific-tasks">'+e.actions.map((a,i)=>'<article class="ar-specific-task" data-task-id="'+esc(a.id)+'"><header><span>任务 '+String(i+1).padStart(2,'0')+'</span><b>'+esc(a.title)+'</b><em>待执行</em></header><div class="ar-task-assignment"><span>建议负责人：'+esc(a.owner)+'</span><span>'+esc(a.period)+'</span></div><p class="ar-task-dependency">前置条件：'+esc(a.dependency)+'</p><ul>'+a.steps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><dl><div><dt>交付材料</dt><dd>'+a.deliverables.map(esc).join('；')+'</dd></div><div><dt>完成要求</dt><dd>'+esc(a.acceptance)+'</dd></div></dl>'+(a.service&&canRecommend&&!t.dismissed&&!S.rejectedLinks.has('service:'+a.service.id)?'<div class="ar-task-service"><span>可选平台服务</span><b>'+esc(a.service.name)+'</b><p>'+esc(a.service.reason)+'</p><div><small>商城展示价 '+esc(a.service.price)+'</small><button type="button" data-ar="task-service" data-turn="'+t.id+'" data-task-id="'+esc(a.id)+'" data-service-id="'+esc(a.service.id)+'">查看服务详情 →</button></div></div>':'')+'</article>').join('')+'</div>';}
function enterpriseCounts(e){return {support:e.items.filter(x=>x.state==='support').length,gap:e.items.filter(x=>['gap','boundary'].includes(x.state)).length,pending:e.items.filter(x=>x.state==='pending').length};}
function enterpriseText(t){const e=t.enterprise,n=enterpriseCounts(e);return '已依据'+e.company+'的当前档案，对照'+e.target+'完成准备度分析。\n'+n.support+'项具有档案支撑，'+n.gap+'项存在明确差距或限制，'+n.pending+'项待核验。\n'+e.items.map(x=>x.req.label+'：'+(x.fact?.value||'未记录')+'；'+({support:'有支撑',gap:'存在差距',boundary:'存在限制',pending:'待核验'}[x.state])).join('\n')+'\n建议先核验口径与凭证，再补强明确差距，最后组织申报材料。以上是准备度分析，不代表正式申报资格结论。';}
function enterpriseHTML(t){const e=t.enterprise,n=enterpriseCounts(e),get=name=>e.facts.find(f=>f.name===name),value=name=>get(name)?.value||'暂无已确认记录';
 const factLink=f=>f?'<button type="button" class="ar-evidence-link" data-ar="enterprise-fact" data-code="'+esc(f.code)+'">查看档案依据 ↗</button>':'';
 const selected=['经营状态','高新技术企业认定','创新型中小企业认定','有效发明专利数量','实用新型专利数量','软件著作权登记数量','研发费用占营收比','研发人员占比','高新技术产品(服务)收入占比','营收复合增长率','研发费用辅助账完整率','纳税信用评级'].map(get).filter(Boolean);
 let html='<section class="ar-enterprise-response" aria-label="企业分析回复"><p class="ar-understood">您希望判断当前企业在“'+esc(e.target)+'”上的准备情况。我会以当前企业档案为依据，区分已有支撑、明确差距和需要核验的事项，再安排准备路径。</p>';
 if(e.phase<1)return html+'<p class="ar-enterprise-progress" role="status">正在读取 '+esc(e.company)+' 的企业数字档案…</p></section>';
 html+='<h3>已读取的企业数据</h3><div class="ar-enterprise-source"><b>'+esc(e.company)+'</b><span>'+esc(e.source)+' · '+e.known.length+'项相关指标</span><small>读取于 '+esc(e.readAt)+'；未记录的字段不补造。</small></div><details class="ar-enterprise-data" open><summary>查看本次分析使用的关键数据（'+selected.length+'项）</summary><div class="ar-comparison-scroll"><table><thead><tr><th>档案指标</th><th>企业现状</th><th>依据</th></tr></thead><tbody>'+selected.map(f=>'<tr><td>'+esc(f.name)+'</td><td>'+esc(f.value)+'</td><td>'+factLink(f)+'</td></tr>').join('')+'</tbody></table></div></details>';
 if(e.phase<2)return html+'<p class="ar-enterprise-progress" role="status">已取得档案数据，正在梳理研发、知识产权与资质现状…</p></section>';
 html+='<h3>从这些数据可以看出</h3><p>知识产权方面，企业有有效发明专利 '+esc(value('有效发明专利数量'))+'、实用新型专利 '+esc(value('实用新型专利数量'))+'、软件著作权 '+esc(value('软件著作权登记数量'))+'。数量反映资产基础，仍需核对权属及与主营产品的关联。</p><p>研发费用占营收比为 '+esc(value('研发费用占营收比'))+'，研发人员占比为 '+esc(value('研发人员占比'))+'；已有研发活动与团队基础，但是否满足目标项目，须进一步统一年度和统计口径。</p><p>现有高企资质：'+esc(value('高新技术企业认定'))+'。创新型中小企业资质：'+esc(value('创新型中小企业认定'))+'。已有且仍有效的资质，应优先核对复核与续期安排，避免按首次申报重复准备。</p>';
 if(e.phase<3)return html+'<p class="ar-enterprise-progress" role="status">正在对照平台已配置的目标条件，逐项判断支撑与缺口…</p></section>';
 html+='<h3>与'+esc(e.target)+'的条件对照</h3><p class="ar-business-note">对照平台当前配置的条件。未配置明确阈值、缺少有效数据或凭证时，标为待核验；已有档案支撑不等同于正式认定。</p><div class="ar-comparison-counts"><span>'+n.support+' 项有档案支撑</span><span>'+n.gap+' 项明确差距 / 限制</span><span>'+n.pending+' 项待核验</span></div><div class="ar-comparison-scroll"><table><thead><tr><th>对照要求</th><th>企业数据与依据</th><th>判断与原因</th></tr></thead><tbody>'+e.items.map(x=>'<tr><td>'+esc(x.req.label)+'</td><td>'+esc(x.fact?.value||'档案无已确认记录')+factLink(x.fact)+'</td><td><b class="ar-condition-'+x.state+'">'+({support:'有档案支撑',gap:'明确差距',boundary:'存在限制',pending:'待核验'}[x.state])+'</b><p>'+esc(x.reason)+'</p></td></tr>').join('')+'</tbody></table></div>';
 html+='<p>'+(n.gap?'发现的明确差距与限制应优先处理，不能用其他优势抵消。':'当前配置的对照项中，未发现明确的数值差距或限制；这不代表全部条件已满足。')+(n.pending?'尚有 '+n.pending+' 项需要核验，须先核对适用批次、统计口径与凭证，再形成申报判断。':'仍应在实际申报前核实材料有效性。')+'</p>';
 if(e.phase<4)return html+'<p class="ar-enterprise-progress" role="status">正在根据差距和待核验事项安排准备顺序…</p></section>';
 html+='<h3>总体规划与建议</h3><p>建议采用“先核验、再补强、后组卷”的路径。已有资质与有效知识产权作为基础，优先处理影响申报判断的口径和证据问题。'+(n.gap?'对已确认差距安排补强；限制情形查清前暂停相关申报推进。':'暂不凭空增加补强任务，先确认待核验项是否形成实际差距。')+'</p><ul class="ar-business-plan"><li><b>建议第1周：明确申报口径。</b>确定目标年度与批次，核验现有资质有效期、政策条件与档案统计年度。</li><li><b>建议第2周：核验并处理缺口。</b>对研发归集、人员结构、收入与成果凭证逐项复核；明确差距后再定补强动作。</li><li><b>具备依据后：组织材料与复核。</b>形成条件—数据—凭证的对应清单，通过内部复核后再决定申报安排。</li></ul><p class="ar-business-note">以上为相对准备节奏，未指定申报截止日，不自动设置任务期限，也不承诺认定结果。</p><h3>具体任务清单</h3>'+enterpriseTasksHTML(t)+'<p class="ar-business-note">'+(t.addedProject?'已加入培育项目：'+esc(t.addedProject)+'。可在任务清单的日历和列表中查看与调整。':'以上清单尚未创建为平台任务。可通过下方“添加到培育项目”保存，再分配负责人和期限。')+'</p></section>';
 return html;
}
function answerText(t){const q=t.packet.text;if(t.enterprise)return enterpriseText(t);if(t.generalOnly)return '按您的选择，本轮只解释一般申报准备方向，暂不判断贵企业是否满足条件。'+(typeof AGENT_TOPICS!=='undefined'&&AGENT_TOPICS[t.card.topic]?.answer||'应对照具体项目与年度，核查主体资格、业务范围、研发活动、知识产权、财务与人员证据。');if(/今年.*变化|最新|实时|政策.*变化/.test(q))return '当前没有取得可逐条核验的新旧政策原文，不能把既有知识当作最新变化。本轮只能说明核对路径：先确定地区、项目与年度，再比较适用对象、认定口径、受理窗口与材料要求；具体变化待提供或接入可靠原文后核验。';if(/通过率|概率/.test(q))return '当前没有经过验证的通过率模型，不能把企业画像、匹配排序或档案完整度换算成准确通过概率。可先按目标项目逐条核验资质、研发、知识产权、收入与人员证据，形成支撑、差距和待核验清单；这不等于对评审结果的承诺。';if(/收费|多少钱|价格|费用多少/.test(q))return '培育或委托服务费用取决于具体范围、交付标准、执行主体和合同约定。当前素材没有确认报价，金额为待定。比较方案应先核对是否包含条件核验、材料整理、专项审计、过程跟进及返工责任，不能将费用与通过结果直接挂钩。';if(/排序/.test(q))return '按指定列重新排列行次序，保留原始表头和每一行数据；原始附件不覆盖。完成后检查排序方向、行数和数据集合。';const topic=t.card.topic,base=typeof AGENT_TOPICS!=='undefined'&&AGENT_TOPICS[topic]?.answer;if(base)return base;if(t.sourceText)return '已依据本轮素材整理业务事实、准备动作和未确定事项。只使用您提供的内容，不补造时间、金额或企业数据；未确定项统一标为待定。';return '系统内暂无与该问题直接对应的已核验能力或资料。本轮只能说明一般处理路径，不能假装查询到外部信息，也不会推送未核验的外部机构。';}
function contentText(t){if(t.enterprise)return '# '+t.enterprise.target+' · 企业分析与任务清单\n\n'+enterpriseText(t)+'\n\n## 具体任务清单\n'+t.enterprise.actions.map((a,i)=>(i+1)+'. '+a.title+'\n建议负责人：'+a.owner+'\n建议时间：'+a.period+'\n前置条件：'+a.dependency+'\n工作内容：'+a.steps.join('；')+'\n交付材料：'+a.deliverables.join('；')+'\n完成要求：'+a.acceptance+(a.service?'\n可选服务：'+a.service.name+'（详情请在平台内查看）':'')).join('\n\n')+'\n\n来源：当前企业档案的原型示例数据；任务尚未创建到平台。';return '# '+t.card.topicName+' · 本轮结果\n\n## 目标\n'+t.card.goal+'\n\n## 业务说明\n'+answerText(t)+'\n\n## 原始素材\n'+(t.sourceText||'仅本轮问题，无其他企业业务数据。')+'\n\n## 准备与核验清单\n1. 明确目标项目与适用年度。\n2. 将已有材料逐项对应目标要求。\n3. 核对数据口径与原始凭证。\n4. 归并待定事项，由资料负责人确认。\n\n## 待定\n'+(t.card.pending.map(x=>'- 待定：'+x).join('\n')||'暂无额外待定项；重要信息请核实。')+'\n\n## 本轮假设\n'+(t.card.assumptions.join('\n')||'无')+'\n\n## 来源\n'+t.card.materials.map(m=>'- '+m.source+'：'+m.summary).join('\n')+'\n\n## 验收标准\n'+t.card.acceptance;}
function wordBlob(text){const xml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));if(typeof buildZip!=='function')throw new Error('Word生成组件未就绪');const parts=[['[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>'],['_rels/.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>'],['word/document.xml','<?xml version="1.0" encoding="UTF-8"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'+text.split('\n').map(line=>'<w:p><w:r><w:t xml:space="preserve">'+xml(line)+'</w:t></w:r></w:p>').join('')+'<w:sectPr/></w:body></w:document>']];return new Blob([buildZip(parts.map(([name,data])=>({name,data:new TextEncoder().encode(data)})))],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});}
function writeArtifact(t){let text=contentText(t),type=t.card.format.startsWith('CSV')?'csv':t.card.format.startsWith('HTML')?'html':'docx';if(/排序/.test(t.packet.text)){const source=t.sourceFiles.find(f=>/\.csv$/i.test(f.name))||t.packet.refs.find(r=>/\.csv$/i.test(r.path||r.title));if(!source)throw new Error('请提供可读取的CSV原件，未用虚构数据替代');const rows=parseCsv(source.text),header=rows[0],column=header?.findIndex(c=>/销售额|销售收入|金额/.test(c))??-1;if(column<0)throw new Error('未找到销售额或金额列，请明确目标列');const body=rows.slice(1);if(body.some(row=>!Number.isFinite(Number((row[column]||'').replace(/,/g,'')))))throw new Error('排序列存在无法识别的数值，未擅自修补');const ascending=/升序/.test(t.packet.text),sorted=[...body].sort((a,b)=>(Number(a[column].replace(/,/g,''))-Number(b[column].replace(/,/g,'')))*(ascending?1:-1));t.sortPassed=body.length===sorted.length&&JSON.stringify(body.map(r=>JSON.stringify(r)).sort())===JSON.stringify(sorted.map(r=>JSON.stringify(r)).sort());text=[header,...sorted].map(row=>row.map(safeCsv).join(',')).join('\r\n');type='csv';}else if(type==='csv')text=[['事项','来源','状态'],[t.card.goal,'用户本轮消息','已整理'],...t.card.pending.map(x=>[x,'理解卡待定','待定']),...t.card.assumptions.map(x=>[x,'显式假设','请核验'])].map(row=>row.map(safeCsv).join(',')).join('\r\n');else if(type==='html')text='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>本轮结果</title><body style="font:15px/1.9 sans-serif;padding:30px;white-space:pre-wrap">'+esc(text)+'</body></html>';const base=t.card.target?t.card.target.split('/').pop().replace(/\.[^.]+$/,''):t.card.topicName+'任务清单',path='/workspace/科创任务/'+base+'.'+type,old=S.files.get(path)||t.packet.refs.find(r=>r.path===path),blob=type==='docx'?wordBlob(text):new Blob([type==='csv'?'\ufeff'+text:text],{type:type==='csv'?'text/csv;charset=utf-8':'text/html;charset=utf-8'});const file={id:uid(),name:base+'.'+type,path,text,blob,type,before:old?.text||((t.card.action==='修改')?(t.sourceFiles[0]?.text||''):''),version:(old?.version||0)+1,turn:t.id,verified:false};S.files.set(path,file);t.outputs=[path];}
async function execute(t){if(t.executing)return;t.executing=true;t.status='running';t.ended=null;t.abort=new AbortController();t.steps=t.card.plan.map(name=>({name,status:'waiting',detail:''}));render();try{for(let i=0;i<t.steps.length;i++){if(t.packet.failure&&!t.degraded){$('#ar-history').insertAdjacentHTML('beforebegin','<div id="ar-connection-progress" class="ar-connection-progress">正在连接 MCP 服务（演练） · 0 / 1 已连接</div>');await delay(650,t.abort.signal);t.status='connection';t.steps[i].detail='检查连接状态：邮箱连接器未接入，演练失败；没有获取外部内容。';$('#ar-connection-progress')?.remove();t.executing=false;render();return;}if(t.packet.loop&&!t.loopApproved){t.status='loop';t.steps[i].detail='检测到相同参数可能重复调用，执行前暂停。';t.executing=false;render();return;}const step=t.steps[i];step.status='running';step.detail='本地演示工具，对应理解卡计划第'+(i+1)+'步';render();await delay(550,t.abort.signal);if(i===0)step.detail='读取 '+t.sourceFiles.filter(f=>f.read).length+' 份文本、'+t.packet.refs.length+' 个指定引用；'+t.unread.length+' 份附件只有元信息。';else if(i===1)step.detail='形成带来源的业务说明，不改变原始附件。';else if(i===2&&['生成','修改'].includes(t.card.action)&&t.mode!=='Ask'){if(/删除|对外发送|发送给|发到.*微信|工作区外|[A-Z]:\\/i.test(t.packet.text)){t.unsupported=true;step.detail='本原型没有磁盘删除、目录外执行或实际发送能力，未执行该操作。';}else{writeArtifact(t);step.detail='已写入 '+t.outputs[0]+'；原始附件保持不变。';}}else step.detail='已核对本步骤的来源、假设、待定和交付范围。';step.status='done';if(t.enterprise)t.enterprise.phase=i+1;render();}
t.answer=answerText(t);if(t.outputs.length)t.answer+='\n\n产物已放入右侧结果区，可打开预览并下载。';if(t.mode==='Ask'&&['生成','修改'].includes(t.card.action))t.answer+='\n\n本轮仅提供咨询解答，不生成或修改文件。如需成品，可点击“生成文件并重新提交”。';const needFile=t.mode!=='Ask'&&['生成','修改'].includes(t.card.action),pass=(!!t.card.topic||!!t.sourceText||/排序/.test(t.packet.text))&&!t.unsupported&&!(t.mode==='Ask'&&['生成','修改'].includes(t.card.action))&&(t.generalOnly||(t.enterprise&&!/通过率|概率|最新|实时|政策.*变化/.test(t.packet.text))||!/通过率|概率|我们.*能报|我们.*适合|我司.*能报|贵司.*符合|今年.*变化|最新|实时|政策.*变化/.test(t.packet.text))&&(!t.enterprise||t.enterprise.facts.length>0)&&(!needFile||t.outputs.length>0)&&!t.unread.length&&!t.degraded;t.checks=[{label:'目标与验收标准',pass,note:pass?t.card.acceptance:'目标尚未完整达成，不能将局部解答或结构模板当作完整交付。'},{label:'处理范围核对',pass:t.mode!=='Ask'||t.outputs.length===0,note:t.mode==='Ask'?'未生成或改写文件。':'只处理当前虚拟任务区，不覆盖原始附件。'},{label:'来源与原始数据',pass:t.sortPassed!==false,note:t.sortPassed===true?'排序前后行数及每行数据一致。':'保留来源，未擅自补造企业数据；重要事实请核实。'},{label:'假设、待定与冲突',pass:!t.card.conflicts.length||!!t.skipped||!!t.year,note:'跳过产生的假设和未定事项已显式列出。'},{label:'导流优先级与解答门控',pass:true,note:'系统功能优先于知识库；外部未核验不跳转，未达验收标准不推荐。'}];const good=t.checks.every(c=>c.pass);t.status=good?'complete':'failed';t.ended=Date.now();t.delivery=t.outputs.length?'已交付 '+t.outputs.length+' 个文件，请在右侧“产物”打开；修改类结果优先查看“变更”。':'本轮解答已在对话区交付。';if(good){for(const path of t.outputs){const file=S.files.get(path);if(file)S.files.set(path,{...file,verified:true});}t.recommendations=t.card.links.filter(link=>link.id!=='outside'&&!S.lastLinks.includes(link.id)&&!S.rejectedLinks.has(link.id)).slice(0,2);if(t.enterprise)t.recommendations=t.enterprise.actions.filter(a=>a.service).map(a=>({id:'service:'+a.service.id,title:a.service.name,kind:'平台服务',note:a.service.reason})).slice(0,2);S.lastLinks=t.recommendations.map(l=>l.id);}else t.recommendations=[];t.executing=false;render();drain();}catch(error){t.executing=false;t.ended=Date.now();if(error.name==='AbortError'){t.status='stopped';t.steps.filter(s=>s.status==='running').forEach(s=>s.status='stopped');render();return;}t.status='failed';t.answer='本轮未执行完成：'+error.message+'。没有伪装成功，不放行服务推荐。';t.checks=[{label:'执行完成',pass:false,note:error.message}];render();drain();}}
function drain(){const t=active();if(t&&['parsing','running','clarify','plan','permission','connection','loop','stopped'].includes(t.status))return;S.active=null;if(S.queue.length)submit(S.queue.shift());else render();}
function enterpriseSummaryHTML(t){const e=t.enterprise,n=enterpriseCounts(e);if(e.phase<4)return '<div class="ar-assessment-summary"><b>'+esc(e.company)+'</b><p>对标目标：'+esc(e.target)+'</p><p>'+(['正在读取企业数字档案…','已取得档案，正在分析企业现状…','正在逐项对照申报条件…','正在形成总体规划与待办建议…'][e.phase]||'正在处理…')+'</p><p class="ar-business-note">完整结论、待办与引导在分析完成后展示。</p></div>';return '<div class="ar-assessment-summary"><b>'+esc(e.company)+'</b><p>对标目标：'+esc(e.target)+'</p><p class="ar-business-note">当前企业档案 · 示例数据</p><div class="ar-assessment-summary-counts"><span><strong>'+n.support+'</strong>有档案支撑</span><span><strong>'+n.gap+'</strong>明确差距 / 限制</span><span><strong>'+n.pending+'</strong>待核验</span></div><h4>优先核验</h4><ul>'+e.actions.slice(0,4).map(a=>'<li>'+esc(a.title)+'</li>').join('')+'</ul><p class="ar-business-note">'+(t.ended?'完整的数据依据、条件对照和准备规划已在左侧回复中展开。':'正在分析，完整结论生成后再给出待办与功能入口。')+'</p><button type="button" class="ar-link" data-ar="navigate" data-link="archive" data-turn="'+t.id+'">查看企业数字档案 →</button></div>';}
function renderResults(){const t=selected(),files=t?t.outputs.map(path=>S.files.get(path)).filter(f=>f?.turn===t.id):[];const analysisOnly=t?.enterprise&&!files.length;$('.ar-results-heading h3').textContent=analysisOnly?'企业分析概览':'结果区';$('[data-tab="artifacts"]').textContent=analysisOnly?'分析概览':'产物';$('#ar-result-count').textContent=String(analysisOnly?t.enterprise.items.length:files.length);$('#ar-result-context').textContent=t?'第'+(S.turns.indexOf(t)+1)+'轮 · '+labels[t.status]:'等待用户发起';root.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===S.tab);b.setAttribute('aria-selected',String(b.dataset.tab===S.tab));});const empty=message=>'<div class="ar-result-empty"><span>▧</span><b>'+message+'</b><p>业务咨询直接在对话区解答；只有您明确要求生成或修改文件时，才会出现文件产物。</p></div>';let html='';if(S.tab==='artifacts')html=files.length?files.map(f=>`<article class="ar-artifact"><div><span>${esc(f.type.toUpperCase())}</span><b>${esc(f.name)}</b><small>v${f.version} · ${f.verified?'自检通过':'待核验'}</small></div><p>${esc(f.path)}</p><details open><summary>查看内容预览</summary><pre>${esc(f.text)}</pre></details><div class="ar-action-row"><button type="button" class="ar-primary" data-ar="download" data-path="${esc(f.path)}">下载文件</button><button type="button" data-ar="reuse" data-path="${esc(f.path)}">@引用于下一轮</button></div></article>`).join(''):(t?.enterprise?enterpriseSummaryHTML(t):empty(t?.mode==='Ask'?'本轮仅咨询，没有文件产物':'本轮尚无产物'));if(S.tab==='web'){const pages=files.filter(f=>f.type==='html');html=pages.length?pages.map(f=>`<article class="ar-artifact"><b>${esc(f.name)}</b><iframe title="网页产物预览" sandbox="" srcdoc="${esc(f.text)}"></iframe><button type="button" data-ar="download" data-path="${esc(f.path)}">下载HTML</button></article>`).join(''):empty('本轮没有网页产物');}if(S.tab==='workspace'){const source=t?.sourceFiles||[];html='<div class="ar-workspace-label">/workspace/科创任务/ <small>虚拟目录</small></div>'+source.map((f,i)=>`<details class="ar-workspace-file"><summary>📎 原始附件 / ${esc(f.name)} <small>只读</small></summary><pre>${esc(f.read?f.text:'未接入该格式正文解析；原始字节仍保留在本机。')}</pre><button type="button" data-ar="download-source" data-turn="${t.id}" data-index="${i}">下载原始附件</button></details>`).join('')+Array.from(S.files.values()).map(f=>`<details class="ar-workspace-file"><summary>▤ ${esc(f.name)} <small>v${f.version}</small></summary><p>${esc(f.path)}</p><pre>${esc(f.text)}</pre></details>`).join('');if(!source.length&&!S.files.size)html+=empty('任务区为空');}if(S.tab==='changes')html=files.length?files.map(f=>`<article class="ar-change"><h4>${f.before?'修改':'新增'} ${esc(f.name)} · v${f.version}</h4><p>${esc(f.path)}</p><details open><summary>查看逐行变更</summary>${diff(f.before,f.text)}</details></article>`).join(''):empty('本轮没有文件变更');$('#ar-result-body').innerHTML=html;}
function diff(before,after){if(!before)return '<pre class="ar-diff-add">'+esc(after.split('\n').map(x=>'+ '+x).join('\n'))+'</pre>';const a=before.split('\n'),b=after.split('\n');let html='';for(let i=0;i<Math.max(a.length,b.length);i++)if(a[i]===b[i])html+='<div>'+esc('  '+(b[i]||''))+'</div>';else{if(a[i]!==undefined)html+='<div class="ar-diff-remove">'+esc('- '+a[i])+'</div>';if(b[i]!==undefined)html+='<div class="ar-diff-add">'+esc('+ '+b[i])+'</div>';}return '<div class="ar-diff">'+html+'</div>';}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
async function addFiles(files){const list=Array.from(files);if(S.drafts.length+list.length>50){info('附件数量超过限制','<p>单轮最多50个附件，请减少文件后重试。</p>');return;}S.drafts.push(...list);renderSources();}
async function reference(){const refs=[...(window.getArchiveGraphFacts?.()||[]).map(f=>({id:f.code,title:f.name,source:'企业档案 · '+f.dimension,text:f.name+'：'+f.value+'；来源：'+f.src})),...Array.from(S.files.values()).map(f=>({id:f.id,title:f.name,path:f.path,text:f.text,source:'任务区 · '+f.path,version:f.version})),...readMemory().map((m,i)=>({id:'memory-'+i,title:m.title,source:m.scope,text:m.text}))];const body='<p>只将您勾选的内容纳入本轮；不会自动读取整份企业档案。</p><div class="ar-reference-list">'+refs.map((r,i)=>`<label><input type="checkbox" data-ref-index="${i}" ${S.refs.some(x=>x.id===r.id)?'checked':''}><span><b>${esc(r.title)}</b><small>${esc(r.source)}</small><p>${esc(r.text.slice(0,130))}</p></span></label>`).join('')+'</div><label class="ar-modal-field">引用批注<input id="ar-ref-note" placeholder="例如：以该口径为准，不改动原值"></label>';const ok=await dialog('@引用资料','选中内容及批注均标为用户指定必须纳入',body,[{label:'取消',value:false},{label:'纳入本轮',value:true,primary:true}]);if(!ok)return;const note=$('#ar-ref-note').value;S.refs=Array.from($('#ar-modal-body').querySelectorAll('[data-ref-index]:checked')).map(i=>({...refs[Number(i.dataset.refIndex)],annotation:note}));renderSources();$('#ar-input').focus();}
async function undo(t,kind){const index=S.turns.indexOf(t),paths=[...new Set(S.turns.slice(index).flatMap(x=>x.outputs))];const ok=await dialog(kind==='edit'?'编辑并从此处重新开始':kind==='refresh'?'重新生成最后一轮':'回退到本轮之前','对话与虚拟产物一起回退，原始附件不变',`<p>将撤回第${index+1}轮及其后${S.turns.length-index-1}轮。</p><ul>${paths.length?paths.map(path=>'<li>'+esc(path)+' → 恢复此前版本；此前不存在则移除</li>').join(''):'<li>没有受影响的产物</li>'}</ul>`,[{label:'取消',value:false},{label:'确认回退'+(kind==='edit'?'并编辑':kind==='refresh'?'并重做':''),value:true,primary:true}]);if(!ok)return;active()?.abort.abort();S.files=new Map(t.snapshot);S.turns=S.turns.slice(0,index);S.active=null;S.selected=last()?.id||null;S.queue=[];S.lastLinks=last()?.recommendations.map(l=>l.id)||[];if(kind==='refresh'){render();submit({...t.packet});return;}if(kind==='edit'){S.drafts=[...t.packet.files];S.refs=[...t.packet.refs];S.voice=t.packet.voice;S.mode=t.mode;$('#ar-input').value=t.packet.text;}render();$('#ar-input').focus();}
async function remember(t){const ok=await dialog('确认沉淀本轮内容','不会自动写记忆；只保存在当前浏览器，不上传云端',`<label class="ar-modal-field">保存范围<select id="ar-memory-scope"><option>项目记忆</option><option>长期偏好</option><option>本地资料库</option></select></label><label class="ar-modal-field">保存内容<textarea id="ar-memory-text" rows="5">${esc(t.card.goal+'\n'+t.answer)}</textarea></label>`,[{label:'取消',value:false},{label:'确认保存',value:true,primary:true}]);if(!ok)return;const text=$('#ar-memory-text').value.trim();if(!text)return;const entries=readMemory();entries.push({title:t.card.topicName+' · 用户确认',scope:$('#ar-memory-scope').value,text});try{localStorage.setItem('whkc-agent-confirmed-memory',JSON.stringify(entries));info('已保存到当前浏览器','<p>下次可通过@引用显式选入；未上传腾讯文档、ima、乐享等服务。</p>');}catch{info('保存失败','<p>浏览器存储不可用，本次未写入记忆。</p>');}}

async function addToCultivation(t){
 if(t.addedProject){goToPage('page-tasks','任务清单');return;}
 const tasks=t.enterprise?.actions||[{id:'followup',title:'核验并落实本轮业务建议',owner:'待分配',steps:[t.card.goal],deliverables:['建议核验与执行记录'],acceptance:'核对本轮建议的适用条件、依据及处理结果。',output:'建议核验与执行记录'}];
 const projects=typeof CULTIVATION_PROJECTS!=='undefined'?Array.from(CULTIVATION_PROJECTS.values()).filter(p=>p.status!=='已完成'):[];
 const body='<p>将本轮 '+tasks.length+' 项任务加入培育项目，并同步到任务清单。</p><label class="ar-modal-field">所属项目<select id="ar-add-project"><option value="">新建培育项目</option>'+projects.map(p=>'<option value="'+esc(p.name)+'">'+esc(p.name)+'</option>').join('')+'</select></label><label class="ar-modal-field">新项目名称<input id="ar-project-name" maxlength="80" value="'+esc((t.enterprise?.target||t.card.topicName)+'准备项目')+'"></label><label class="ar-modal-field">开始日期<input type="date" id="ar-project-start" value="'+cultivationTaskToday()+'"></label><label><input type="checkbox" id="ar-project-schedule" checked> 按建议顺序安排执行日期，显示到任务日历</label><p class="ar-business-note">负责人和日期可在任务清单中调整；不会自动下单服务。</p><details><summary>查看将添加的任务</summary><ul>'+tasks.map(a=>'<li>'+esc(a.title)+' · '+esc(a.owner)+'</li>').join('')+'</ul></details>';
 const ok=await dialog('添加到培育项目','保存本轮分析任务，跨项目统一管理',body,[{label:'取消',value:false},{label:'确认添加',value:true,primary:true}]);if(!ok)return;
 const existing=$('#ar-add-project').value,name=$('#ar-project-name').value.trim(),date=$('#ar-project-start').value,schedule=$('#ar-project-schedule').checked;
 if(!existing&&!name){info('请输入项目名称','<p>未创建项目或任务，请重新填写。</p>');return;}
 if(schedule&&!date){info('请选择开始日期','<p>任务尚未添加，请选择日期后再试。</p>');return;}
 const result=window.TaskCalendar?.addAgentTasks({existing,name,start:date,schedule,tasks,source:t.id});if(!result){info('暂未完成添加','<p>任务日历组件未就绪，未创建重复数据。</p>');return;}
 t.addedProject=result.project;t.events.push('已添加到培育项目：'+result.project+'，共'+result.count+'项任务');render();showToast('已添加 '+result.count+' 项任务到「'+result.project+'」','success');
}
function navigate(id,t){if(id==='cultivation')openProjectModal(t.card.topicName);else if(id==='training')openAgentTraining();else if(id==='policy')goToPage('page-policy','政策发现');else if(id==='service')goToPage('page-mall','服务商城');else if(id==='archive')goToPage('page-archive','企业数字档案');else if(id==='knowledge')goToPage('page-skills','技能');}
root.addEventListener('click',async event=>{const tab=event.target.closest('[data-tab]');if(tab){S.tab=tab.dataset.tab;renderResults();return;}const b=event.target.closest('[data-ar]');if(!b)return;const action=b.dataset.ar;if(action==='task-service'){const turn=S.turns.find(x=>x.id===b.dataset.turn),task=turn?.enterprise?.actions.find(x=>x.id===b.dataset.taskId),product=typeof MALL_PRODUCTS!=='undefined'?MALL_PRODUCTS.find(x=>x.id===b.dataset.serviceId):null;if(!task?.service||task.service.id!==product?.id||!['complete','accepted'].includes(turn.status))return;openMallDetail(product.name);const back=document.querySelector('#service-detail-view .sd-back');if(back){back.textContent='← 返回智能体任务清单';back.onclick=()=>{closeServiceDetail();goToPage('page-agent','智能体广场');root.querySelector('[data-task-id="'+task.id+'"]')?.scrollIntoView({block:'center'});};}return;}if(action==='enterprise-fact'){window.openArchiveGraphFact?.(b.dataset.code);return;}if(action==='prompt'){const t=S.turns.find(x=>x.id===b.dataset.turn)||last();$('#ar-input').value=b.dataset.prompt;$('#ar-input').focus();return;}if(action==='example'){const c=introductions[S.agent?.id],q=c?.questions[Number(b.dataset.example)];if(q){$('#ar-input').value=q[1];S.mode='Agent';$('#ar-input').focus();}return;}const t=S.turns.find(x=>x.id===b.dataset.turn)||active()||last();
if(action==='add-project'){addToCultivation(t);return;}if(action==='send'){submit();return;}if(action==='attach'){$('#ar-files').click();return;}if(action==='reference'){reference();return;}
if(action==='back'){if(['running','parsing'].includes(active()?.status))active().abort.abort();root.style.display='none';document.getElementById('pgMatrix').style.display='block';return;}
if(action==='new'){if(S.turns.length){const ok=await dialog('开始新对话','清空本次对话与虚拟产物；已下载文件不受影响','<p>请先下载需要保留的产物。</p>',choices);if(!ok)return;}start(S.agent);return;}
if(action==='scope'){info('上下文与授权范围','<ol><li>本轮消息、您上传的附件与勾选的@引用。</li><li>与当前问题相关的历史对话。</li><li>您确认保存到浏览器的记忆，可通过@选入。</li><li>未接入腾讯文档、ima、乐享、企微或邮箱。</li></ol><p>不扫描磁盘目录，不上传原始数据。完全访问仅作用于浏览器中的虚拟任务区。</p>');return;}
if(action==='voice'){const ok=await dialog('语音转写输入','本原型不录音、不调用云端转写；请粘贴确认后的文本','<label class="ar-modal-field">确认后的转写文本<textarea id="ar-voice" rows="5"></textarea></label>',[{label:'取消',value:false},{label:'确认文本并加入输入',value:true,primary:true}]);if(ok){S.voice=$('#ar-voice').value;renderSources();}return;}
if(action==='modal-close'){S.resolve?.(false);S.resolve=null;modal.close();return;}if(action==='remove-file'){S.drafts.splice(Number(b.dataset.index),1);renderSources();return;}if(action==='remove-ref'){S.refs.splice(Number(b.dataset.index),1);renderSources();return;}if(action==='remove-voice'){S.voice='';renderSources();return;}if(action==='dequeue'){S.queue.splice(Number(b.dataset.index),1);render();return;}
if(action==='stop'){$('#ar-connection-progress')?.remove();active()?.abort.abort();return;}
if(action==='clarify'){const o=t.options[Number(b.dataset.index)];if(o.attach){$('#ar-files').click();return;}if(o.reference){reference();return;}t.events.push(o.label);t.resolved=true;if(o.assessmentTarget){t.assessmentTarget=o.assessmentTarget;t.events.push('选择对标目标：'+o.assessmentTarget);prepare(t);return;}if(o.general){t.generalOnly=true;t.overrideAction='查询';t.assumptions.push('用户选择先了解一般条件，本轮不作企业适配判断。');}if(o.year){t.year=o.year;t.assumptions.push('用户确认本轮采用'+o.year+'年口径；不改原始素材。');}if(o.action)t.overrideAction=o.action;if(o.topic)t.packet.text+='\n用户补充：'+o.topic;const ready=understand(t);render();if(ready)continueTurn(t);return;}
if(action==='skip'){t.events.push('跳过反问');t.skipped=true;t.assumptions.push(t.conflict?'用户跳过年度冲突确认，年份保留待定，仅整理通用结构。':'用户跳过对象确认，采用通用口径，不作企业适配结论。');const ready=understand(t);if(t.conflict)t.card.pending.push('申请年度待定，建议与资料负责人确认');render();if(ready)continueTurn(t);return;}
if(action==='execute'){t.events.push('确认计划v'+t.planVersion+'并开始执行');t.planConfirmed=true;continueTurn(t);return;}
if(action==='adjust'){const ok=await dialog('调整计划','调整后仍停留在计划确认，需再次点击开始执行','<label class="ar-modal-field">补充要求<textarea id="ar-plan-edit" rows="4"></textarea></label>',[{label:'取消',value:false},{label:'更新计划',value:true,primary:true}]);if(ok&&$('#ar-plan-edit').value.trim()){const text=$('#ar-plan-edit').value;t.packet.text+='\n计划补充：'+text;t.events.push(text);t.planVersion++;understand(t);t.status='plan';render();}return;}
if(action==='permission'){permission(t);return;}if(action==='continue-loop'){t.events.push('仅继续执行一次');t.loopApproved=true;execute(t);return;}if(action==='retry'){t.events.push('重新检查连接状态');execute(t);return;}if(action==='degrade'){t.events.push('仅使用当前本地素材继续');t.degraded=true;t.assumptions.push('外部资料未取得，仅使用当前素材；相关事项待核验。');understand(t);execute(t);return;}if(action==='terminate'){t.abort.abort();t.status='cancelled';t.ended=Date.now();render();drain();return;}if(action==='resume'){t.events.push('基于已有内容继续');execute(t);return;}
if(['edit','rollback','refresh'].includes(action)){undo(t,action);return;}if(action==='switch-agent'){S.mode='Agent';submit({...t.packet,mode:'Agent'});return;}if(action==='show-turn'){S.selected=t.id;S.tab=t.card.action==='修改'?'changes':'artifacts';renderResults();return;}if(action==='accept'){t.status='accepted';t.events.push('验收本轮结果');render();return;}if(action==='dismiss'){t.dismissed=true;t.enterprise?.actions.filter(a=>a.service).forEach(a=>S.rejectedLinks.add('service:'+a.service.id));t.recommendations.forEach(l=>S.rejectedLinks.add(l.id));t.events.push('跳过本轮推荐');render();return;}if(action==='remember'){remember(t);return;}if(action==='navigate'){navigate(b.dataset.link,t);return;}
if(action==='download'){const f=S.files.get(b.dataset.path);if(f)download(f.blob,f.name);return;}if(action==='download-source'){const f=t.sourceFiles[Number(b.dataset.index)];if(f)download(f.blob,f.name);return;}if(action==='reuse'){const f=S.files.get(b.dataset.path);if(f){S.refs.push({id:f.id,title:f.name,path:f.path,text:f.text,version:f.version,source:'任务区 · '+f.path});renderSources();$('#ar-input').focus();}return;}
});
$('#ar-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();submit();}});$('#ar-files').addEventListener('change',e=>{addFiles(e.target.files);e.target.value='';});
$('#ar-dropzone')?.addEventListener('drop',()=>{});
$('.ar-conversation').addEventListener('dragover',e=>{e.preventDefault();$('.ar-conversation').classList.add('dragging');});$('.ar-conversation').addEventListener('dragleave',()=>$('.ar-conversation').classList.remove('dragging'));$('.ar-conversation').addEventListener('drop',e=>{e.preventDefault();$('.ar-conversation').classList.remove('dragging');addFiles(e.dataTransfer.files);});
$('#ar-scenarios').innerHTML=scenarios.map((s,i)=>`<button type="button" data-scenario="${i}"><b>${esc(s[0])}</b></button>`).join('');
$('#ar-scenarios').addEventListener('click',e=>{const b=e.target.closest('[data-scenario]');if(!b)return;const s=scenarios[Number(b.dataset.scenario)];S.mode=s[1];S.drafts=[];S.refs=[];S.voice='';$('#ar-fail').checked=s[4]==='failure';$('#ar-loop').checked=s[4]==='loop';if(s[3]==='csv')S.drafts=[new File(['客户,销售额\n客户甲,100\n客户乙,300\n客户丙,200'],'销售额示例.csv',{type:'text/csv'})];if(s[3]==='notes')S.drafts=[new File(['目标：2027年申报高企。\n先整理知识产权、研发费用和人员证明。\n技术负责人核对知识产权清单。\n财务负责人整理研发辅助账。\n预算上限：待定。\n只整理准备清单，不估计通过结果。'],'申报准备笔记.txt',{type:'text/plain'})];if(s[3]==='conflict')S.drafts=[new File(['申请年度：2027。\n目标项目：高新技术企业认定。\n先整理资料清单。'],'2026年申报笔记.txt',{type:'text/plain'})];$('#ar-input').value=s[2];render();$('#ar-input').focus();});
function start(agent){active()?.abort.abort();if(modal.open)modal.close();S.agent=agent||S.agent;S.turns=[];S.active=null;S.queue=[];S.files=new Map();S.drafts=[];S.refs=[];S.voice='';S.selected=null;S.tab='artifacts';S.lastLinks=[];S.rejectedLinks=new Set();S.mode='Agent';S.permission='default';document.getElementById('pgMatrix').style.display='none';root.style.display='block';$('#ar-name').textContent=S.agent?.name||'智能体运行台';$('#ar-input').value='';$('#ar-fail').checked=false;$('#ar-loop').checked=false;render();}
runAgent=start;
window.AgentRuntimeDemo={start,submit,inspect:()=>({turns:S.turns,queue:S.queue,files:Array.from(S.files.values()),active:S.active}),parseCsv};
render();
})();
